/**
 * P12 chat-core: the shared model and hooks behind Composer, Attachment Chip, Message,
 * Conversation and Chat Shell. Import from here.
 */
export * from "./types";
export * from "./group-messages";
export * from "./attachments";
export * from "./composer-keys";
export * from "./use-stick-to-bottom";
export * from "./use-chat-adapter";
export * from "./use-autosize";

/**
 * Chat message types, structurally compatible with Vercel AI SDK v5+ `UIMessage`.
 *
 * Eased never imports `ai`: these mirror its shapes, so `useChat().messages` passes straight
 * into Eased components and Eased messages pass back into `setMessages`. Only the parts Eased
 * renders are spelled out; every other part type still type-checks through `ChatUnknownPart`.
 *
 * Tool-call state (`input-streaming`, `output-available` …) is owned by `thinking-core`'s
 * `ToolState`; here it stays a plain string so this file has no cross-lane dependency.
 */

/** `useChat().status`: `submitted` is waiting for the first chunk, `streaming` is receiving it. */
export type ChatStatus = "submitted" | "streaming" | "ready" | "error";

export type ChatRole = "system" | "user" | "assistant";

/** Streaming state of a text or reasoning part. */
export type ChatPartState = "streaming" | "done";

export type ChatTextPart = { type: "text"; text: string; state?: ChatPartState };
export type ChatReasoningPart = { type: "reasoning"; text: string; state?: ChatPartState };

/** An attached file. `url` is a hosted URL or a `data:` URL, as AI SDK expects. */
export type ChatFilePart = { type: "file"; mediaType: string; filename?: string; url: string };

export type ChatSourceUrlPart = { type: "source-url"; sourceId: string; url: string; title?: string };
export type ChatStepStartPart = { type: "step-start" };

/** A tool call: `type` is `tool-<name>`. `state` mirrors thinking-core's `ToolState`. */
export type ChatToolPart = {
  type: `tool-${string}`;
  toolCallId: string;
  state: string;
  input?: unknown;
  output?: unknown;
  errorText?: string;
};

/** Anything else AI SDK may send (`data-*`, `dynamic-tool`, `source-document` …). */
export type ChatUnknownPart = { type: string; [key: string]: unknown };

export type ChatMessagePart =
  | ChatTextPart
  | ChatReasoningPart
  | ChatFilePart
  | ChatSourceUrlPart
  | ChatStepStartPart
  | ChatToolPart
  | ChatUnknownPart;

/**
 * One message. Same shape as AI SDK's `UIMessage<METADATA>`: `id`, `role`, `parts`, and an
 * optional `metadata` you define (Eased reads `authorId` and `createdAt` from it when present).
 */
export type ChatMessage<Metadata = unknown> = {
  id: string;
  role: ChatRole;
  parts: ChatMessagePart[];
  metadata?: Metadata;
};

export const isTextPart = (p: ChatMessagePart): p is ChatTextPart => p.type === "text";
export const isFilePart = (p: ChatMessagePart): p is ChatFilePart => p.type === "file";
export const isReasoningPart = (p: ChatMessagePart): p is ChatReasoningPart => p.type === "reasoning";
export const isToolPart = (p: ChatMessagePart): p is ChatToolPart =>
  p.type.startsWith("tool-") && typeof (p as ChatToolPart).toolCallId === "string";

/** The message's text parts joined, e.g. for Copy. */
export function messageText(message: Pick<ChatMessage, "parts">) {
  return message.parts.filter(isTextPart).map((p) => p.text).join("");
}

/** True while a reply is on its way: submitted or streaming. */
export const isBusy = (status: ChatStatus | undefined) => status === "submitted" || status === "streaming";

import type { ChatMessage } from "./types";

/** Where a message sits in a run of consecutive messages from one author. */
export type GroupPosition = "single" | "first" | "middle" | "last";

export type GroupOptions<M extends ChatMessage = ChatMessage> = {
  /**
   * Who wrote the message. Default: `metadata.authorId` when present, else the role, so a
   * group chat splits by person and an AI chat by user/assistant.
   */
  getAuthor?: (message: M) => string;
  /** When the message was sent, ms. Default: `metadata.createdAt` (number, string or Date). */
  getTime?: (message: M) => number | undefined;
  /** A pause longer than this starts a new group even for the same author, ms. Default 5 minutes. */
  gap?: number;
};

export type MessageGroup<M extends ChatMessage = ChatMessage> = {
  /** Stable key: the first message's id. */
  key: string;
  author: string;
  role: M["role"];
  messages: { message: M; position: GroupPosition }[];
};

type Meta = { authorId?: unknown; createdAt?: unknown } | undefined;

const defaultAuthor = (m: ChatMessage) => {
  const id = (m.metadata as Meta)?.authorId;
  return typeof id === "string" ? id : m.role;
};

const defaultTime = (m: ChatMessage) => {
  const t = (m.metadata as Meta)?.createdAt;
  if (typeof t === "number") return t;
  if (typeof t === "string" || t instanceof Date) {
    const ms = new Date(t).getTime();
    return Number.isNaN(ms) ? undefined : ms;
  }
  return undefined;
};

function positionOf(index: number, length: number): GroupPosition {
  if (length === 1) return "single";
  if (index === 0) return "first";
  return index === length - 1 ? "last" : "middle";
}

/**
 * Splits a flat message list into runs of consecutive messages from one author. Use the
 * groups to render one avatar and name per run, and each message's `position` to merge
 * bubble corners. Pure and cheap: call it in render.
 */
export function groupMessages<M extends ChatMessage>(messages: readonly M[], options: GroupOptions<M> = {}): MessageGroup<M>[] {
  const { getAuthor = defaultAuthor as (m: M) => string, getTime = defaultTime as (m: M) => number | undefined, gap = 5 * 60_000 } = options;
  const groups: { key: string; author: string; role: M["role"]; items: M[] }[] = [];
  let lastTime: number | undefined;

  for (const message of messages) {
    const author = getAuthor(message);
    const time = getTime(message);
    const current = groups[groups.length - 1];
    const paused = time !== undefined && lastTime !== undefined && time - lastTime > gap;
    if (current && current.author === author && current.role === message.role && !paused) current.items.push(message);
    else groups.push({ key: message.id, author, role: message.role, items: [message] });
    if (time !== undefined) lastTime = time;
  }

  return groups.map(({ key, author, role, items }) => ({
    key,
    author,
    role,
    messages: items.map((message, i) => ({ message, position: positionOf(i, items.length) })),
  }));
}

/** Each message's group position by id, for lists you render flat. */
export function groupPositions<M extends ChatMessage>(messages: readonly M[], options?: GroupOptions<M>) {
  const map = new Map<string, GroupPosition>();
  for (const group of groupMessages(messages, options)) for (const { message, position } of group.messages) map.set(message.id, position);
  return map;
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import type { ChatFilePart } from "./types";

/* ---------- The model ---------------------------------------------------------- */

export type AttachmentKind = "image" | "file";
export type AttachmentStatus = "uploading" | "done" | "error";

/** One attachment in a composer or a sent message. Plain data: store it anywhere. */
export type Attachment = {
  id: string;
  name: string;
  /** `image` shows a thumbnail; everything else is a file chip. */
  kind: AttachmentKind;
  /** MIME type, e.g. `image/png`, `application/pdf`. */
  mediaType: string;
  /** Bytes. */
  size?: number;
  /** Where the file lives once uploaded (or a `data:` URL). Sent as the `file` part's `url`. */
  url?: string;
  /** A local preview for images while they upload (an object URL). */
  previewUrl?: string;
  /** Default `done`. */
  status?: AttachmentStatus;
  /** Upload progress 0–1 while `uploading`; leave it out when unknown (the ring spins). */
  progress?: number;
  /** Shown under the name when `status` is `error`, e.g. "Over 20 MB". */
  error?: string;
  /** The original file, when it came from the user's device. */
  file?: File;
};

export const kindOf = (mediaType: string): AttachmentKind => (mediaType.startsWith("image/") ? "image" : "file");

let counter = 0;
const newId = () => (typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `att-${Date.now()}-${++counter}`);

/** An attachment for a picked, dropped or pasted file. Images get an object-URL preview: call `releaseAttachment` when done. */
export function attachmentFromFile(file: File, status: AttachmentStatus = "uploading"): Attachment {
  const mediaType = file.type || "application/octet-stream";
  const kind = kindOf(mediaType);
  return {
    id: newId(),
    name: file.name || (kind === "image" ? "Pasted image" : "File"),
    kind,
    mediaType,
    size: file.size,
    previewUrl: kind === "image" ? URL.createObjectURL(file) : undefined,
    status,
    file,
  };
}

/** Frees an attachment's object-URL preview. */
export function releaseAttachment(a: Attachment) {
  if (a.previewUrl?.startsWith("blob:")) URL.revokeObjectURL(a.previewUrl);
}

/** `1.2 MB`, `840 KB`, with a no-break space. */
export function formatBytes(bytes: number, locale?: Intl.LocalesArgument) {
  if (bytes < 1000) return `${new Intl.NumberFormat(locale).format(bytes)}\u00a0${bytes === 1 ? "byte" : "bytes"}`;
  const units = ["byte", "kilobyte", "megabyte", "gigabyte"] as const;
  let i = 0;
  let n = bytes;
  while (n >= 1000 && i < units.length - 1) {
    n /= 1000;
    i++;
  }
  return new Intl.NumberFormat(locale, { style: "unit", unit: units[i], unitDisplay: "short", maximumFractionDigits: n < 10 && i > 0 ? 1 : 0 })
    .format(n)
    .replace(" ", " ");
}

/** The short type label for a file chip: `PDF`, `CSV`, `ZIP`. */
export function fileTypeLabel(a: Pick<Attachment, "name" | "mediaType">) {
  const ext = a.name.includes(".") ? a.name.split(".").pop() : undefined;
  return (ext || a.mediaType.split("/").pop() || "file").slice(0, 4).toUpperCase();
}

/** An AI SDK `file` part for a finished attachment (`sendMessage({ text, files })`). Returns null until it has a URL. */
export function toFilePart(a: Attachment): ChatFilePart | null {
  const url = a.url ?? (a.status === "done" || a.status === undefined ? a.previewUrl : undefined);
  return url ? { type: "file", mediaType: a.mediaType, filename: a.name, url } : null;
}

/** The reverse: an attachment to render a sent `file` part. */
export function fromFilePart(part: ChatFilePart, id = part.url): Attachment {
  return { id, name: part.filename ?? "Attachment", kind: kindOf(part.mediaType), mediaType: part.mediaType, url: part.url, status: "done" };
}

/* ---------- useAttachments ---------------------------------------------------- */

/** Uploads one file. Report progress 0–1; resolve with where it now lives. Respect `signal`. */
export type UploadFn = (file: File, ctx: { onProgress: (fraction: number) => void; signal: AbortSignal }) => Promise<{ url: string }>;

export type UseAttachmentsOptions = {
  /** Upload each file as it is added. Without it, files are kept locally (`done`, previewed by object URL). */
  upload?: UploadFn;
  /** Same syntax as `<input accept>`, e.g. `"image/*,.pdf"`. Files that do not match are rejected. */
  accept?: string;
  /** Bytes; larger files are added with an error so the user sees why. */
  maxSize?: number;
  /** Extra files past this are dropped and reported through `onReject`. */
  maxFiles?: number;
  /** Called with files that were refused, and why. */
  onReject?: (rejected: { file: File; reason: "type" | "count" }[]) => void;
  /** Controlled list. Pair with `onChange`. */
  value?: Attachment[];
  defaultValue?: Attachment[];
  onChange?: (attachments: Attachment[]) => void;
};

export function matchesAccept(file: File, accept?: string) {
  if (!accept) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return accept.split(",").some((raw) => {
    const rule = raw.trim().toLowerCase();
    if (!rule) return false;
    if (rule.startsWith(".")) return name.endsWith(rule);
    if (rule.endsWith("/*")) return type.startsWith(rule.slice(0, -1));
    return type === rule;
  });
}

/**
 * The attachment state machine for a composer: add (pick, drop, paste), upload with progress,
 * cancel on remove, retry on error, and clear after sending. Object-URL previews are freed
 * when an attachment leaves the list and on unmount.
 */
export function useAttachments({ upload, accept, maxSize, maxFiles, onReject, value, defaultValue, onChange }: UseAttachmentsOptions = {}) {
  const [inner, setInner] = useState<Attachment[]>(defaultValue ?? []);
  const attachments = value ?? inner;
  const list = useRef(attachments);
  const controllers = useRef(new Map<string, AbortController>());
  const latest = useRef({ upload, onChange, controlled: value !== undefined });
  useLayoutEffect(() => {
    list.current = attachments;
    latest.current = { upload, onChange, controlled: value !== undefined };
  });

  const commit = useCallback((next: Attachment[]) => {
    for (const a of list.current) if (!next.some((n) => n.id === a.id)) releaseAttachment(a);
    list.current = next;
    if (!latest.current.controlled) setInner(next);
    latest.current.onChange?.(next);
  }, []);

  const patch = useCallback(
    (id: string, changes: Partial<Attachment>) => {
      if (!list.current.some((a) => a.id === id)) return;
      commit(list.current.map((a) => (a.id === id ? { ...a, ...changes } : a)));
    },
    [commit],
  );

  const start = useCallback(
    (a: Attachment) => {
      const fn = latest.current.upload;
      if (!fn || !a.file) return;
      const controller = new AbortController();
      controllers.current.set(a.id, controller);
      let last = 0;
      fn(a.file, {
        signal: controller.signal,
        onProgress: (fraction) => {
          // Throttle to visible steps; the ring springs between them.
          if (controller.signal.aborted || (fraction - last < 0.01 && fraction < 1)) return;
          last = fraction;
          patch(a.id, { progress: Math.min(1, Math.max(0, fraction)) });
        },
      }).then(
        ({ url }) => {
          controllers.current.delete(a.id);
          if (!controller.signal.aborted) patch(a.id, { status: "done", progress: 1, url, error: undefined });
        },
        (err: unknown) => {
          controllers.current.delete(a.id);
          if (!controller.signal.aborted) patch(a.id, { status: "error", error: err instanceof Error ? err.message : "Upload failed" });
        },
      );
    },
    [patch],
  );

  const add = useCallback(
    (files: Iterable<File> | ArrayLike<File>) => {
      const incoming = Array.from(files);
      const rejected: { file: File; reason: "type" | "count" }[] = [];
      const room = maxFiles === undefined ? Infinity : Math.max(0, maxFiles - list.current.length);
      const added: Attachment[] = [];
      for (const file of incoming) {
        if (!matchesAccept(file, accept)) rejected.push({ file, reason: "type" });
        else if (added.length >= room) rejected.push({ file, reason: "count" });
        else {
          const tooBig = maxSize !== undefined && file.size > maxSize;
          const a = attachmentFromFile(file, tooBig ? "error" : latest.current.upload ? "uploading" : "done");
          if (tooBig) a.error = `Over ${formatBytes(maxSize!)}`;
          added.push(a);
        }
      }
      if (rejected.length) onReject?.(rejected);
      if (!added.length) return [];
      commit([...list.current, ...added]);
      for (const a of added) if (a.status === "uploading") start(a);
      return added;
    },
    [accept, maxFiles, maxSize, onReject, commit, start],
  );

  const remove = useCallback(
    (id: string) => {
      controllers.current.get(id)?.abort();
      controllers.current.delete(id);
      commit(list.current.filter((a) => a.id !== id));
    },
    [commit],
  );

  const retry = useCallback(
    (id: string) => {
      const a = list.current.find((x) => x.id === id);
      if (!a?.file || !latest.current.upload) return;
      if (maxSize !== undefined && a.file.size > maxSize) return;
      const next = { ...a, status: "uploading" as const, progress: undefined, error: undefined };
      commit(list.current.map((x) => (x.id === id ? next : x)));
      start(next);
    },
    [commit, start, maxSize],
  );

  /** Empties the list after a send. Previews are kept alive for `keepPreviews` (the sent message may still show them). */
  const clear = useCallback(
    ({ keepPreviews = true }: { keepPreviews?: boolean } = {}) => {
      for (const c of controllers.current.values()) c.abort();
      controllers.current.clear();
      if (keepPreviews) list.current = [];
      commit([]);
    },
    [commit],
  );

  useEffect(() => {
    const ctrl = controllers.current;
    return () => {
      for (const c of ctrl.values()) c.abort();
      for (const a of list.current) releaseAttachment(a);
    };
  }, []);

  const uploading = attachments.some((a) => a.status === "uploading");
  const failed = attachments.some((a) => a.status === "error");

  return {
    attachments,
    add,
    remove,
    retry,
    clear,
    update: patch,
    /** True while any file is still uploading: hold Send until it is false. */
    uploading,
    /** True when any file failed: Send skips those files. */
    failed,
    /** The finished attachments as AI SDK `file` parts. */
    fileParts: attachments.map(toFilePart).filter((p): p is ChatFilePart => p !== null),
  };
}

"use client";

import { useCallback, useRef, type KeyboardEvent } from "react";

/** A `/command` or `@mention` being typed: what the Pro Slash and Mention menus open on. */
export type ComposerTrigger = {
  /** The trigger character, e.g. `/` or `@`. */
  char: string;
  /** What follows it so far, e.g. `"summ"` for `/summ`. */
  query: string;
  /** Index of the trigger character in the value. */
  start: number;
  /** Index just past the query (the caret). */
  end: number;
};

/**
 * The trigger under the caret, or null. `/` counts only at the start of a line (so URLs and
 * fractions never open the slash menu); other characters count after whitespace or at the
 * start. The query stops at whitespace.
 */
export function findTrigger(value: string, caret: number, chars: readonly string[] = ["/", "@"]): ComposerTrigger | null {
  let i = caret - 1;
  while (i >= 0 && !/\s/.test(value[i])) {
    if (chars.includes(value[i])) {
      const before = i === 0 ? "\n" : value[i - 1];
      const ok = value[i] === "/" ? before === "\n" : /\s/.test(before);
      return ok ? { char: value[i], query: value.slice(i + 1, caret), start: i, end: caret } : null;
    }
    i--;
  }
  return null;
}

/** Replaces a trigger with the picked item, e.g. `@ma` → `@Maya Chen `. Returns the new value and caret. */
export function replaceTrigger(value: string, trigger: ComposerTrigger, insert: string) {
  const next = value.slice(0, trigger.start) + insert + value.slice(trigger.end);
  return { value: next, caret: trigger.start + insert.length };
}

export type ComposerKeyOptions = {
  /** Called on the submit chord when `canSubmit` is true. */
  onSubmit: () => void;
  /** False when there is nothing to send or a reply is streaming. Default true. */
  canSubmit?: boolean;
  /** `enter` (default): Enter sends, Shift+Enter breaks the line. `mod-enter`: ⌘/Ctrl+Enter sends. */
  submitOn?: "enter" | "mod-enter";
  /** ⌘↑ / Ctrl+↑ anywhere, or ↑ in an empty composer: edit your last message. */
  onEditLast?: () => void;
  /** Escape: e.g. stop the stream, or blur. Return true if handled. */
  onEscape?: () => boolean | void;
  /**
   * Runs first on every keydown. Return true to claim the key: an open Slash or Mention menu
   * uses this for ↑ ↓ Enter Tab Escape, and the composer then ignores it.
   */
  intercept?: (event: KeyboardEvent<HTMLTextAreaElement>) => boolean;
  /** Characters that open a trigger menu. Default `["/", "@"]`. */
  triggerChars?: readonly string[];
  /** The trigger under the caret after each keystroke or caret move, or null. Wire the Pro menus here. */
  onTrigger?: (trigger: ComposerTrigger | null) => void;
};

/**
 * Keyboard handling for a chat composer: the submit chord (IME-safe: Enter that confirms a
 * Japanese or Chinese composition never sends), edit-last, Escape, and trigger detection for
 * slash commands and mentions. Spread the result onto the `<textarea>`.
 */
export function useComposerKeys({
  onSubmit,
  canSubmit = true,
  submitOn = "enter",
  onEditLast,
  onEscape,
  intercept,
  triggerChars = ["/", "@"],
  onTrigger,
}: ComposerKeyOptions) {
  const lastTrigger = useRef<string | null>(null);

  const report = useCallback(
    (el: HTMLTextAreaElement) => {
      if (!onTrigger) return;
      const t = el.selectionStart === el.selectionEnd ? findTrigger(el.value, el.selectionStart, triggerChars) : null;
      const sig = t ? `${t.char}${t.start}:${t.query}` : null;
      if (sig === lastTrigger.current) return;
      lastTrigger.current = sig;
      onTrigger(t);
    },
    [onTrigger, triggerChars],
  );

  const onKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (intercept?.(e)) return;
      // 229 covers Safari, which fires keydown for the composition-confirming Enter without isComposing.
      if (e.nativeEvent.isComposing || e.keyCode === 229) return;
      const mod = e.metaKey || e.ctrlKey;

      if (e.key === "Enter") {
        const chord = submitOn === "enter" ? !e.shiftKey && !e.altKey : mod;
        if (!chord) return;
        e.preventDefault();
        if (canSubmit) onSubmit();
        return;
      }
      if (e.key === "ArrowUp" && onEditLast && (mod || e.currentTarget.value === "")) {
        e.preventDefault();
        onEditLast();
        return;
      }
      if (e.key === "Escape" && onEscape?.()) e.preventDefault();
    },
    [intercept, submitOn, canSubmit, onSubmit, onEditLast, onEscape],
  );

  const onSelect = useCallback((e: { currentTarget: HTMLTextAreaElement }) => report(e.currentTarget), [report]);

  return { onKeyDown, onSelect, onInput: onSelect };
}

"use client";

import { animate, motionValue, type AnimationPlaybackControls } from "motion/react";
import { useCallback, useLayoutEffect, useRef, useState } from "react";
import { smooth, useSafeReducedMotion } from "../../lib/motion";

export type UseStickToBottomOptions = {
  /** Within this many px of the bottom counts as "at the bottom" and re-locks. Default 48. */
  threshold?: number;
  /** Follow new content on a smooth spring (default) or jump. Reduced motion always jumps. */
  animated?: boolean;
  /** Start at the bottom on mount. Default true. */
  initial?: boolean;
};

export type StickToBottom = {
  /** Put on the scrolling element (`overflow-y: auto`). */
  scrollRef: (el: HTMLElement | null) => void;
  /** Put on the element inside it that grows as messages stream. */
  contentRef: (el: HTMLElement | null) => void;
  /** True while following. False once the user scrolls up: show a "Jump to latest" pill. */
  isAtBottom: boolean;
  /** Scroll to the bottom and follow again (the pill's onClick). */
  scrollToBottom: (opts?: { animated?: boolean }) => void;
  /** Stop following without scrolling, e.g. when the user selects text. */
  stopFollowing: () => void;
  /**
   * Call just before prepending older messages: the next growth keeps what is on screen
   * still instead of pushing it down.
   */
  preserveScroll: () => void;
};

/**
 * Keeps a chat scrolled to the newest message while it streams, and lets go the moment the
 * user scrolls up (wheel, touch, keyboard or scrollbar). Following rides one spring that is
 * retargeted as each chunk lands, so bursty tokens glide instead of stepping; it never fights
 * the user, because any scroll that is not the spring's own stops it. Scrolling back within
 * `threshold` of the bottom locks on again.
 */
export function useStickToBottom({ threshold = 48, animated = true, initial = true }: UseStickToBottomOptions = {}): StickToBottom {
  const reduced = useSafeReducedMotion();
  const [isAtBottom, setIsAtBottom] = useState(initial);
  const scroller = useRef<HTMLElement | null>(null);
  const content = useRef<HTMLElement | null>(null);
  const locked = useRef(initial);
  const top = useRef(motionValue(0));
  const anim = useRef<AnimationPlaybackControls | null>(null);
  /** Where the spring last put scrollTop; scroll events that match it are ours. */
  const expected = useRef<number | null>(null);
  const anchor = useRef<number | null>(null);
  const opts = useRef({ threshold, animated, reduced });
  useLayoutEffect(() => {
    opts.current = { threshold, animated, reduced };
  });

  const setBottom = useCallback((v: boolean) => {
    locked.current = v;
    setIsAtBottom((prev) => (prev === v ? prev : v));
  }, []);

  const stop = useCallback(() => {
    anim.current?.stop();
    anim.current = null;
    expected.current = null;
  }, []);

  const follow = useCallback(
    (animate_ = opts.current.animated) => {
      const el = scroller.current;
      if (!el) return;
      const target = el.scrollHeight - el.clientHeight;
      if (target - el.scrollTop < 1) return;
      if (!animate_ || opts.current.reduced) {
        stop();
        expected.current = target;
        el.scrollTop = target;
        return;
      }
      // Retargeting a running spring keeps its velocity, so a stream of chunks reads as one glide.
      if (!anim.current) top.current.jump(el.scrollTop);
      anim.current = animate(top.current, target, { ...smooth, onComplete: () => (anim.current = null) });
    },
    [stop],
  );

  // The spring writes scrollTop; remember what it wrote so the scroll listener can tell it from the user.
  useLayoutEffect(
    () =>
      top.current.on("change", (v) => {
        const el = scroller.current;
        if (!el) return;
        expected.current = v;
        el.scrollTop = v;
      }),
    [],
  );

  const onResize = useCallback(() => {
    const el = scroller.current;
    if (!el) return;
    if (anchor.current !== null) {
      expected.current = el.scrollHeight - anchor.current;
      el.scrollTop = expected.current;
      anchor.current = null;
      return;
    }
    if (locked.current) follow();
  }, [follow]);

  const onScroll = useCallback(() => {
    const el = scroller.current;
    if (!el) return;
    const max = el.scrollHeight - el.clientHeight;
    if (expected.current !== null && Math.abs(el.scrollTop - Math.min(expected.current, max)) < 2) return;
    // Not the spring: the user (or the browser) moved it.
    stop();
    setBottom(max - el.scrollTop <= opts.current.threshold);
  }, [setBottom, stop]);

  const onWheel = useCallback(
    (e: WheelEvent) => {
      if (e.deltaY < 0 && anim.current) {
        stop();
        setBottom(false);
      }
    },
    [setBottom, stop],
  );
  const onTouch = useCallback(() => {
    if (anim.current) stop();
  }, [stop]);

  const observers = useRef<{ ro: ResizeObserver | null }>({ ro: null });
  const getObserver = () => (observers.current.ro ??= new ResizeObserver(() => onResize()));

  const scrollRef = useCallback(
    (el: HTMLElement | null) => {
      const prev = scroller.current;
      if (prev) {
        prev.removeEventListener("scroll", onScroll);
        prev.removeEventListener("wheel", onWheel);
        prev.removeEventListener("touchmove", onTouch);
        getObserver().unobserve(prev);
      }
      scroller.current = el;
      if (!el) return;
      el.addEventListener("scroll", onScroll, { passive: true });
      el.addEventListener("wheel", onWheel, { passive: true });
      el.addEventListener("touchmove", onTouch, { passive: true });
      // The viewport shrinking (a composer growing below it) must keep the bottom in view too.
      getObserver().observe(el);
      if (locked.current) {
        expected.current = el.scrollHeight;
        el.scrollTop = el.scrollHeight;
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [onScroll, onWheel, onTouch],
  );

  const contentRef = useCallback(
    (el: HTMLElement | null) => {
      if (content.current) getObserver().unobserve(content.current);
      content.current = el;
      if (el) getObserver().observe(el);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  const scrollToBottom = useCallback(
    ({ animated: a }: { animated?: boolean } = {}) => {
      setBottom(true);
      follow(a ?? opts.current.animated);
    },
    [follow, setBottom],
  );

  const stopFollowing = useCallback(() => {
    stop();
    setBottom(false);
  }, [setBottom, stop]);

  const preserveScroll = useCallback(() => {
    const el = scroller.current;
    if (el) anchor.current = el.scrollHeight - el.scrollTop;
  }, []);

  useLayoutEffect(
    () => () => {
      anim.current?.stop();
      observers.current.ro?.disconnect();
    },
    [],
  );

  return { scrollRef, contentRef, isAtBottom, scrollToBottom, stopFollowing, preserveScroll };
}

import type { Attachment } from "./attachments";
import { toFilePart } from "./attachments";
import type { ChatFilePart, ChatMessage, ChatStatus } from "./types";

/** What the Composer hands to `onSubmit`. */
export type ComposerSubmission = {
  text: string;
  /** Every attachment in the row, finished or not; `files` is the sendable subset. */
  attachments: Attachment[];
  /** The finished attachments as AI SDK `file` parts. */
  files: ChatFilePart[];
};

/**
 * The slice of AI SDK v5+ `useChat()` the adapter reads. Structural, so Eased has no `ai`
 * dependency: pass the hook's return value as is.
 */
export type UseChatLike<M extends ChatMessage = ChatMessage> = {
  messages: M[];
  status: ChatStatus;
  sendMessage: (message: { text: string; files?: ChatFilePart[] }) => unknown;
  stop: () => unknown;
  regenerate?: (options?: { messageId?: string }) => unknown;
  error?: Error | undefined;
};

/** The Composer props the adapter fills. */
export type ChatComposerBindings = {
  status: ChatStatus;
  onSubmit: (submission: ComposerSubmission) => void;
  onStop: () => void;
};

/**
 * Wires AI SDK's `useChat` into Eased:
 *
 * ```tsx
 * const chat = useChat();
 * const { composer, messages, status } = fromUseChat(chat);
 * <Composer {...composer} />
 * ```
 *
 * A plain function (no hooks), so it is free to call in render.
 */
export function fromUseChat<M extends ChatMessage>(chat: UseChatLike<M>) {
  const composer: ChatComposerBindings = {
    status: chat.status,
    onSubmit: ({ text, files }) => {
      void chat.sendMessage(files.length ? { text, files } : { text });
    },
    onStop: () => void chat.stop(),
  };
  return {
    messages: chat.messages,
    status: chat.status,
    error: chat.error,
    composer,
    regenerate: chat.regenerate,
  };
}

/** Builds the submission the Composer passes to `onSubmit`. */
export function toSubmission(text: string, attachments: Attachment[]): ComposerSubmission {
  return { text, attachments, files: attachments.map(toFilePart).filter((p): p is ChatFilePart => p !== null) };
}

"use client";

import { animate, useMotionValue, type AnimationPlaybackControls } from "motion/react";
import { useCallback, useLayoutEffect, useRef, type RefObject } from "react";
import { smooth, useSafeReducedMotion } from "../../lib/motion";

/**
 * The composer's height spring, for a bare `<textarea>` with no shell of its own (Textarea
 * draws a bordered field; the composer draws the border around more than the text). The
 * textarea is sized at once, so the caret never leaves view, and the returned motion value
 * springs a clip around it. Put `height` on the clip's `style`.
 */
export function useAutosize(ref: RefObject<HTMLTextAreaElement | null>, { minRows = 1, maxRows = 6, value }: { minRows?: number; maxRows?: number; value?: string }) {
  const reduced = useSafeReducedMotion();
  const height = useMotionValue<number | "auto">("auto");
  const spring = useRef<AnimationPlaybackControls | null>(null);

  const resize = useCallback(
    (animated: boolean) => {
      const el = ref.current;
      if (!el) return;
      const cs = getComputedStyle(el);
      const line = parseFloat(cs.lineHeight) || 20;
      const chrome = parseFloat(cs.paddingTop) + parseFloat(cs.paddingBottom);
      const max = maxRows * line + chrome;
      el.style.height = "0px";
      const content = el.scrollHeight;
      const target = Math.round(Math.min(max, Math.max(minRows * line + chrome, content)));
      el.style.height = `${target}px`;
      el.style.overflowY = content > max + 1 ? "auto" : "hidden";
      const from = height.get();
      if (from === target) return;
      spring.current?.stop();
      if (!animated || reduced || from === "auto") height.jump(target);
      else spring.current = animate(height, target, smooth);
    },
    [ref, minRows, maxRows, reduced, height],
  );

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    resize(false);
    let width = el.offsetWidth;
    const ro = new ResizeObserver(() => {
      if (el.offsetWidth === width) return;
      width = el.offsetWidth;
      resize(false);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref, resize]);

  useLayoutEffect(() => {
    if (value !== undefined) resize(true);
  }, [value, resize]);

  return { height, resize };
}
